int count = 0;
for (int i = 0; i < 4; ++i) {
    for (int j = i + 1; j < 4; ++j) {
        auto vi = h->vertex(i);
        auto vj = h->vertex(j);
        if (!vi || !vj) continue;
        auto pi = vi->point();
        auto pj = vj->point();
        double sq = CGAL::squared_distance(pi, pj);
        if (sq > threshold) ++count;
    }
}
return count;

